def entrainer_bigrammes(texte):
    mots = texte.lower().split()
    modele = {}
    for a, b in zip(mots, mots[1:]):
        suivants = modele.setdefault(a, {})
        suivants[b] = suivants.get(b, 0) + 1
    return modele

def mot_suivant(modele, mot):
    if mot not in modele:
        return None
    suivants = modele[mot]
    return min(suivants, key=lambda s: (-suivants[s], s))

def predire(poids, biais, x):
    z = sum(w * xi for w, xi in zip(poids, x)) + biais
    return 1 if z > 0 else 0

def entrainer_perceptron(exemples, epoques, pas):
    poids = [0.0] * len(exemples[0][0])
    biais = 0.0
    for _ in range(epoques):
        for x, y in exemples:
            erreur = y - predire(poids, biais, x)
            poids = [w + pas * erreur * xi for w, xi in zip(poids, x)]
            biais = biais + pas * erreur
    return poids, biais

