import math

def sigmoide(z):
    return 1 / (1 + math.exp(-z))

def perte_log(p, y):
    return round(-(y * math.log(p) + (1 - y) * math.log(1 - p)), 4)

def pas_logistique(poids, biais, x, y, pas):
    p = sigmoide(sum(w * xi for w, xi in zip(poids, x)) + biais)
    ecart = p - y
    nouveaux = [round(w - pas * ecart * xi, 4) for w, xi in zip(poids, x)]
    return nouveaux, round(biais - pas * ecart, 4)

