exercice.solution:
def distance2(a, b):
    return sum((x - y) ** 2 for x, y in zip(a, b))

def kmeans(points, centres, iterations):
    centres = [tuple(c) for c in centres]
    for _ in range(iterations):
        groupes = [[] for _ in centres]
        for p in points:
            i = min(range(len(centres)), key=lambda k: distance2(p, centres[k]))
            groupes[i].append(p)
        centres = [tuple(sum(c) / len(g) for c in zip(*g)) if g else centres[i]
                   for i, g in enumerate(groupes)]
    return [tuple(round(v, 2) for v in c) for c in centres]

