exercice.solution:
from collections import Counter

def gini(etiquettes):
    n = len(etiquettes)
    return round(1 - sum((c / n) ** 2 for c in Counter(etiquettes).values()), 3)

def meilleur_seuil(valeurs, etiquettes):
    n = len(valeurs)
    meilleur, meilleur_score = None, None
    for s in sorted(set(valeurs)):
        gauche = [e for v, e in zip(valeurs, etiquettes) if v <= s]
        droite = [e for v, e in zip(valeurs, etiquettes) if v > s]
        if not droite:
            continue
        score = len(gauche) / n * gini(gauche) + len(droite) / n * gini(droite)
        if meilleur_score is None or score < meilleur_score:
            meilleur, meilleur_score = s, score
    return meilleur

