import math

def sigmoide(z):
    return 1 / (1 + math.exp(-z))

def couche(entrees, poids, biais):
    return [sigmoide(sum(x * w for x, w in zip(entrees, ws)) + b) for ws, b in zip(poids, biais)]

def xor(a, b):
    cachee = couche([a, b], [[20, 20], [-20, -20]], [-10, 30])
    sortie = couche(cachee, [[20, 20]], [-30])[0]
    return round(sortie)

