def entrainer(exemples):
    scores = {}
    for texte, etiquette in exemples:
        delta = 1 if etiquette == "positif" else -1
        for mot in texte.lower().split():
            scores[mot] = scores.get(mot, 0) + delta
    return scores

def predire(modele, texte):
    total = sum(modele.get(mot, 0) for mot in texte.lower().split())
    return "positif" if total > 0 else "négatif"
